-- "Eliminar servicio" (ficha del servicio): deletes a recurring service with
-- its cycles and cost periods, in one transaction -- only when nothing
-- billed or paid hangs from it. Members have no DELETE policy on
-- recurring_services / recurring_service_occurrences, so this is security
-- definer with its own membership check.
--
-- Refused while the service has any of:
-- * sales_allocations on its cycles (invoices assigned to them, suggested or confirmed);
-- * a cycle linked to an invoice the old way (recurring_service_occurrences.sales_document_id);
-- * a sales document generated by the old Epic 5 generator (sales_documents.recurring_service_id);
-- * cost_service_allocations on its cost periods (purchase invoices, suggested or confirmed);
-- * MS licenses pool shares on its cycles (recurring_service_cost_allocations).
-- Those have to be removed first; the app lists which ones.

create or replace function public.delete_recurring_service(p_service_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_service public.recurring_services;
  v_sales int;
  v_linked int;
  v_legacy int;
  v_costs int;
  v_pool int;
  v_bulk int;
  v_cycles int;
  v_cost_periods int;
begin
  if v_user_id is null then
    raise exception 'Authentication required to delete a recurring service';
  end if;

  select * into v_service from public.recurring_services where id = p_service_id for update;
  if v_service.id is null then
    raise exception 'Servicio no encontrado';
  end if;

  if not exists (
    select 1 from public.company_memberships cm
    where cm.company_id = v_service.company_id and cm.user_id = v_user_id
  ) then
    raise exception 'No tenés acceso a este servicio';
  end if;

  select count(*) into v_sales
  from public.sales_allocations sa
  join public.recurring_service_occurrences o on o.id = sa.recurring_service_period_id
  where o.recurring_service_id = p_service_id;

  select count(*) into v_linked
  from public.recurring_service_occurrences o
  where o.recurring_service_id = p_service_id and o.sales_document_id is not null;

  select count(*) into v_legacy
  from public.sales_documents sd
  where sd.recurring_service_id = p_service_id;

  select count(*) into v_costs
  from public.cost_service_allocations a
  join public.recurring_service_cost_periods cp on cp.id = a.cost_period_id
  where cp.recurring_service_id = p_service_id;

  select count(*) into v_pool
  from public.recurring_service_cost_allocations a
  join public.recurring_service_occurrences o on o.id = a.occurrence_id
  where o.recurring_service_id = p_service_id;

  if v_sales + v_linked + v_legacy + v_costs + v_pool > 0 then
    raise exception 'El servicio tiene asignaciones: % de ventas, % ciclos con factura vinculada, % documentos de venta generados, % de facturas de compra y % del pool de licencias. Quitálas antes de eliminarlo.',
      v_sales, v_linked, v_legacy, v_costs, v_pool;
  end if;

  delete from public.recurring_service_occurrence_bulk_changes b
  using public.recurring_service_occurrences o
  where b.occurrence_id = o.id and o.recurring_service_id = p_service_id;
  get diagnostics v_bulk = row_count;

  delete from public.recurring_service_occurrences o where o.recurring_service_id = p_service_id;
  get diagnostics v_cycles = row_count;

  delete from public.recurring_service_cost_periods cp where cp.recurring_service_id = p_service_id;
  get diagnostics v_cost_periods = row_count;

  delete from public.recurring_services s where s.id = p_service_id;

  return jsonb_build_object('cycles', v_cycles, 'cost_periods', v_cost_periods, 'bulk_changes', v_bulk);
end;
$$;

revoke execute on function public.delete_recurring_service(uuid) from public, anon;
grant execute on function public.delete_recurring_service(uuid) to authenticated, service_role;
